use super::*;

/// The pure half of [`open_briefs`] — the coord log's TEXT folded into the briefs still open.
///
/// Split from its read so the fold is a record of its own: it is the part worth comparing against the
/// rest of the graph, and the part a test can drive from a string rather than a temp file. A missing
/// log reads as empty text, so the shell keeps `unwrap_or_default` and this half never sees an error.
pub fn briefs_of(text: &str) -> Vec<OpenBrief> {    let mut open: Vec<OpenBrief> = Vec::new();
    let mut acked: std::collections::HashSet<String> = std::collections::HashSet::new();
    for line in text.lines() {
        let f: Vec<&str> = line.split('\t').collect();
        // ts, pane, kind, then the payload
        if f.len() < 4 {
            continue;
        }
        let (at, from, kind) = (f[0], f[1], f[2]);
        match kind {
            KIND_BRIEF if f.len() >= 5 => {
                let target = f[3];
                open.push(OpenBrief {
                    id: brief_id(from, at, target),
                    from: from.to_string(),
                    target: target.to_string(),
                    body: f[4].to_string(),
                    at: at.to_string(),
                    reference: f.get(5).unwrap_or(&"").to_string(),
                });
            }
            KIND_BRIEF_ACK => {
                acked.insert(f[3].to_string());
            }
            _ => {}
        }
    }
    open.retain(|b| !acked.contains(&b.id));
    open
}
